<?php
declare(strict_types=1);
$config=require __DIR__.'/config.php';
date_default_timezone_set('Europe/Moscow');
function db(): PDO { global $config; static $db; if(!$db){$db=new PDO($config['dsn'],$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$db->exec("SET time_zone = '+03:00'");}return $db; }
function query(string $sql,array $args=[]): PDOStatement {$s=db()->prepare($sql);$s->execute($args);return $s;}
function json_out(mixed $data,int $code=200): never {http_response_code($code);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;}
function fail(string $message,int $code=400): never {json_out(['error'=>$message],$code);}
function input(): array {static $d;if($d===null){if((int)($_SERVER['CONTENT_LENGTH']??0)>20000)fail('Слишком большой запрос',413);$d=json_decode(file_get_contents('php://input'),true);if(!is_array($d))fail('Ожидается JSON');}return $d;}
function field(array $d,string $k,int $max=500): string {$v=$d[$k]??'';if(!is_string($v)||!trim($v)||mb_strlen($v)>$max)fail('Проверьте поле: '.$k);return trim($v);}
function session_init(): void {if(session_status()===PHP_SESSION_ACTIVE)return;global $config;session_name('gv_session');session_set_cookie_params(['httponly'=>true,'secure'=>str_starts_with($config['base_url'],'https://'),'samesite'=>'Lax','path'=>'/']);ini_set('session.use_strict_mode','1');session_start();$_SESSION['csrf']??=bin2hex(random_bytes(32));$_SESSION['visitor']??=bin2hex(random_bytes(24));}
function csrf(): void {if(!hash_equals($_SESSION['csrf'],$_SERVER['HTTP_X_CSRF_TOKEN']??''))fail('Обновите страницу и повторите действие',403);}
function admin(): void {if(empty($_SESSION['admin'])||time()-($_SESSION['login_at']??0)>7200)fail('Требуется вход администратора',401);}
function ip_hash(): string {global $config;if(strlen($config['secret'])<32)throw new RuntimeException('APP_SECRET not configured');return hash_hmac('sha256',$_SERVER['REMOTE_ADDR']??'cli',$config['secret']);}
function rate_limit(string $kind,int $limit,int $seconds): void {$key=hash('sha256',ip_hash().$kind);$slot=(int)floor(time()/$seconds);query('INSERT INTO rate_limits (bucket,slot,hits) VALUES (?,?,1) ON DUPLICATE KEY UPDATE hits=hits+1',[$key,$slot]);if((int)query('SELECT hits FROM rate_limits WHERE bucket=? AND slot=?',[$key,$slot])->fetchColumn()>$limit)fail('Слишком много запросов. Повторите позже.',429);}
function safe_xml(string $s): SimpleXMLElement {if(strlen($s)>2000000||stripos($s,'<!DOCTYPE')!==false||stripos($s,'<!ENTITY')!==false)throw new RuntimeException('Unsafe XML');libxml_use_internal_errors(true);$x=simplexml_load_string($s,SimpleXMLElement::class,LIBXML_NONET|LIBXML_NOCDATA);if(!$x)throw new RuntimeException('Invalid XML');return $x;}
function external(string $key,string $url,int $ttl): array {
 $old=query('SELECT payload,updated_at FROM cache WHERE cache_key=?',[$key])->fetch();
 if($old && time()-strtotime($old['updated_at'])<$ttl)return ['body'=>$old['payload'],'updated_at'=>$old['updated_at'],'stale'=>false];
 $ch=curl_init($url);$body='';if(getenv('OUTBOUND_HTTPS_PROXY'))curl_setopt($ch,CURLOPT_PROXY,getenv('OUTBOUND_HTTPS_PROXY')); curl_setopt_array($ch,[CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>15,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_USERAGENT=>'GameVerse/1.0 (RSS reader)',CURLOPT_WRITEFUNCTION=>function($ch,$chunk)use(&$body){if(strlen($body)+strlen($chunk)>2000000)return 0;$body.=$chunk;return strlen($chunk);}]);
 $ok=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$curlError=curl_error($ch);curl_close($ch);if($ok===false||$status!==200)error_log('Upstream '.$key.': HTTP '.$status.' '.$curlError);
 if($ok!==false&&$status===200){try{safe_xml($body);query('INSERT INTO cache(cache_key,payload,updated_at) VALUES (?,?,NOW()) ON DUPLICATE KEY UPDATE payload=VALUES(payload),updated_at=NOW()',[$key,$body]);return ['body'=>$body,'updated_at'=>date('Y-m-d H:i:s'),'stale'=>false];}catch(Throwable $e){error_log('Invalid upstream XML: '.$key);}}
 if($old)return ['body'=>$old['payload'],'updated_at'=>$old['updated_at'],'stale'=>true];
 throw new RuntimeException('Источник временно недоступен');
}
function rates(): array {$v=external('cbr','https://www.cbr.ru/scripts/XML_daily.asp',21600);$x=safe_xml($v['body']);$r=['RUB'=>1.0];foreach($x->Valute as $c){$n=(int)$c->Nominal;if($n>0)$r[(string)$c->CharCode]=(float)str_replace(',','.',(string)$c->Value)/$n;}return ['rates'=>$r,'date'=>(string)$x['Date'],'source'=>'Банк России','source_url'=>'https://www.cbr.ru/currency_base/daily/','stale'=>$v['stale'],'fetched_at'=>$v['updated_at']];}
function moderate(string $text): void {if(query('SELECT 1 FROM blocked_hosts WHERE host_hash=?',[ip_hash()])->fetchColumn())fail('Публикация с этого адреса ограничена',403);foreach(query('SELECT phrase FROM blocked_words')->fetchAll() as $r){if(mb_stripos($text,$r['phrase'])!==false)fail('Сообщение содержит запрещённое выражение');}}
function feed_items(): array {global $config;$items=[];foreach(query('SELECT * FROM news ORDER BY published_at DESC LIMIT 50')->fetchAll() as $n)$items[]=['id'=>'local-'.$n['id'],'title'=>$n['title'],'text'=>$n['body'],'url'=>$config['base_url'].'/services/news.html#news-'.$n['id'],'source'=>'GameVerse','date'=>$n['published_at']];$status=['ok'=>false,'stale'=>false];try{$v=external('ixbt','https://www.ixbt.com/export/news/rss.xml',900);$x=safe_xml($v['body']);foreach(array_slice(iterator_to_array($x->channel->item,false),0,30) as $n){$link=(string)$n->link;if(!preg_match('~^https://([a-z0-9-]+\.)*(ixbt\.com|ixbt\.games)/~i',$link))continue;$stamp=strtotime((string)$n->pubDate);$items[]=['id'=>'rss-'.hash('sha256',$link),'title'=>mb_substr(strip_tags((string)$n->title),0,300),'text'=>'','url'=>$link,'source'=>'iXBT — технологии','date'=>$stamp?date('Y-m-d H:i:s',$stamp):$v['updated_at']];}$status=['ok'=>true,'stale'=>$v['stale'],'fetched_at'=>$v['updated_at']];}catch(Throwable $e){$status['message']='Внешняя лента временно недоступна; показаны новости GameVerse.';}$unique=[];foreach($items as $n)$unique[$n['url']]=$n;$items=array_values($unique);usort($items,fn($a,$b)=>strcmp($b['date'],$a['date']));return ['items'=>$items,'external'=>$status];}
